mapper.select:
select * from ( select mc.ID, mc.MACHINE_CODE, mc.CHUCK_CODE, mc.CHUCK_NAME, mc.INCH_SIZE, mc.REMARK, mc.IS_DELETE, mc.CREATE_BY, mc.CREATE_TIME, mc.UPDATE_BY, mc.UPDATE_TIME, mi.MACHINE_NAME from T_TQ_MACHINE_CHUCK mc left join T_TQ_MACHINE_INFO mi on mc.MACHINE_CODE = mi.MACHINE_CODE and mi.IS_DELETE = '0' where mc.IS_DELETE = '0'
and mc.MACHINE_CODE = #{machineCode}
order by mc.create_time desc ) t
